<script setup>
import { t } from '../i18n';
defineProps({ modelValue:Object, editing:Boolean });
const emit=defineEmits(['update:modelValue']);
function set(form,key,value){emit('update:modelValue',{...form,[key]:value});}
const names={daily:'每天',weekdays:'工作日',weekends:'周末',mon:'每周一',tue:'每周二',wed:'每周三',thu:'每周四',fri:'每周五',sat:'每周六',sun:'每周日'};
</script>
<template><div class="form-grid schedule-editor"><label>{{ t("计划类型") }}<select :value="modelValue.kind" @change="set(modelValue,'kind',$event.target.value)"><option v-if="editing" value="unchanged">{{ t("保留现有计划") }}</option><option value="cron">{{ t("按时间重复") }}</option><option value="custom">{{ t("自定义 Cron") }}</option><option v-if="!editing || modelValue.kind==='once'" value="once">{{ t("仅执行一次") }}</option></select></label><template v-if="modelValue.kind==='cron'"><label>{{ t("时间") }}<input type="time" :value="modelValue.time" @input="set(modelValue,'time',$event.target.value)" /></label><label>{{ t("重复") }}<select :aria-label="t(&quot;重复&quot;)" :value="modelValue.frequency" @change="set(modelValue,'frequency',$event.target.value)"><option v-for="(name,key) in names" :key="key" :value="key">{{ t(name) }}</option></select></label></template><label v-if="modelValue.kind==='custom'">{{ t("Cron 表达式") }}<input :value="modelValue.cron" placeholder="0 9 * * 1-5" @input="set(modelValue,'cron',$event.target.value)" /></label><label v-if="modelValue.kind==='once'">{{ t("执行时间") }}<input :value="modelValue.fire_at" :disabled="editing" placeholder="2026-10-01T09:00:00+08:00" @input="set(modelValue,'fire_at',$event.target.value)" /><small v-if="editing">{{ t("当前接口不支持修改单次执行时间；可保留或改为重复计划。") }}</small></label><label v-if="modelValue.kind!=='unchanged'">{{ t("时区") }}<input :value="modelValue.timezone" :disabled="editing" @input="set(modelValue,'timezone',$event.target.value)" /></label></div></template>
